// ---- src/core/parse.js
// Pure parsing for uploaded or pasted data. No DOM, no network.
// CSV follows RFC 4180: quoted fields, "" escapes, CRLF or LF, embedded
// newlines inside quotes, optional UTF-8 byte order mark.

const DEFAULT_MAX_BYTES = 5 * 1024 * 1024;

class ParseError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ParseError';
  }
}

function stripBom(text) {
  return text.charCodeAt(0) === 0xfeff ? text.slice(1) : text;
}

function byteLength(text) {
  return new TextEncoder().encode(text).length;
}

function formatBytes(n) {
  if (n < 1024) return n + ' B';
  if (n < 1024 * 1024) return (n / 1024).toFixed(n < 10240 ? 1 : 0) + ' KB';
  return (n / (1024 * 1024)).toFixed(1) + ' MB';
}

// Returns an array of records, each an array of strings.
function parseCsv(input, { delimiter = ',' } = {}) {
  const text = stripBom(String(input));
  const rows = [];
  let row = [];
  let field = '';
  let inQuotes = false;
  let afterQuote = false; // just closed a quoted field
  let fieldStarted = false;
  let line = 1;
  const endField = () => {
    row.push(field);
    field = '';
    fieldStarted = false;
    afterQuote = false;
  };
  const endRow = () => {
    endField();
    rows.push(row);
    row = [];
  };
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (inQuotes) {
      if (c === '"') {
        if (text[i + 1] === '"') {
          field += '"';
          i++;
        } else {
          inQuotes = false;
          afterQuote = true;
        }
      } else {
        if (c === '\n') line++;
        field += c;
      }
      continue;
    }
    if (c === '"') {
      if (!fieldStarted && !afterQuote) {
        inQuotes = true;
        fieldStarted = true;
      } else if (afterQuote) {
        throw new ParseError('Unexpected quote on line ' + line + '.');
      } else {
        field += c; // a stray quote inside an unquoted field is kept as text
      }
    } else if (c === delimiter) {
      endField();
    } else if (c === '\r' || c === '\n') {
      if (c === '\r' && text[i + 1] === '\n') i++;
      endRow();
      line++;
    } else {
      if (afterQuote) throw new ParseError('Unexpected text after a closing quote on line ' + line + '.');
      field += c;
      fieldStarted = true;
    }
  }
  if (inQuotes) throw new ParseError('A quoted field is not closed (started before the end of the file).');
  if (fieldStarted || afterQuote || field !== '' || row.length > 0) endRow();
  return rows;
}

// First record is the header. Duplicate or blank headers are made unique.
function csvToObjects(rows) {
  if (rows.length === 0) return [];
  const seen = new Map();
  const headers = rows[0].map((raw, i) => {
    let name = raw.trim() || 'column_' + (i + 1);
    const n = (seen.get(name) || 0) + 1;
    seen.set(name, n);
    if (n > 1) name = name + '_' + n;
    return name;
  });
  const out = [];
  for (let r = 1; r < rows.length; r++) {
    const rec = rows[r];
    if (rec.length === 1 && rec[0] === '') continue; // blank line
    const obj = {};
    headers.forEach((h, i) => {
      obj[h] = i < rec.length ? rec[i] : '';
    });
    out.push(obj);
  }
  return out;
}

function parseNdjson(input) {
  const lines = stripBom(String(input)).split(/\r?\n/);
  const out = [];
  for (let i = 0; i < lines.length; i++) {
    const l = lines[i].trim();
    if (!l) continue;
    try {
      out.push(JSON.parse(l));
    } catch {
      throw new ParseError('Line ' + (i + 1) + ' is not valid JSON.');
    }
  }
  return out;
}

function parseJson(input) {
  try {
    return JSON.parse(stripBom(String(input)));
  } catch (e) {
    throw new ParseError('Not valid JSON: ' + e.message);
  }
}

function detectFormat(text, name = '') {
  const ext = /\.([a-z0-9]+)$/i.exec(name)?.[1]?.toLowerCase();
  if (ext === 'csv') return 'csv';
  if (ext === 'ndjson' || ext === 'jsonl') return 'ndjson';
  if (ext === 'json') return 'json';
  const t = stripBom(text).trimStart();
  if (t.startsWith('[')) return 'json';
  if (t.startsWith('{')) {
    const lines = t.split(/\r?\n/).filter((l) => l.trim());
    return lines.length > 1 && lines.every((l) => l.trimStart().startsWith('{')) ? 'ndjson' : 'json';
  }
  return 'csv';
}

// Returns { data, format }. CSV becomes an array of objects keyed by header.
function parseText(text, { name = '', format } = {}) {
  const body = stripBom(String(text));
  if (!body.trim()) throw new ParseError('There is no data to read.');
  let fmt = format || detectFormat(body, name);
  if (fmt === 'csv') return { data: csvToObjects(parseCsv(body)), format: 'csv' };
  if (fmt === 'ndjson') return { data: parseNdjson(body), format: 'ndjson' };
  try {
    return { data: parseJson(body), format: 'json' };
  } catch (err) {
    // A .json name on newline-delimited content: try NDJSON before giving up.
    if (!format) {
      try {
        return { data: parseNdjson(body), format: 'ndjson' };
      } catch {
        /* fall through to the original error */
      }
    }
    throw err;
  }
}

function checkSize(bytes, maxBytes = DEFAULT_MAX_BYTES) {
  if (bytes > maxBytes) {
    return 'That is ' + formatBytes(bytes) + '. The limit is ' + formatBytes(maxBytes) + '.';
  }
  return null;
}

// ---- src/core/network-guard.js
// Counts fetch, XMLHttpRequest and sendBeacon calls made while a callback runs,
// so a page can truthfully say "0 network requests while processing".
//
// Honest limits: it sees only those three APIs. It does not see image or
// script loads, WebSockets, or requests from other origins' frames. It counts
// every call from this page during the window, including unrelated ones.

async function countNetworkCalls(fn, env = globalThis) {
  const calls = [];
  const restore = [];
  const note = (kind, target) => {
    let url = '';
    try {
      const raw = typeof target === 'string' ? target : target?.url || String(target);
      const u = new URL(raw, env.location?.href || 'http://localhost/');
      url = u.origin + u.pathname; // drop query and hash
    } catch {
      url = '(unparsed)';
    }
    calls.push({ kind, url });
  };

  if (typeof env.fetch === 'function') {
    const original = env.fetch;
    env.fetch = function (input, ...rest) {
      note('fetch', input);
      return original.call(this, input, ...rest);
    };
    restore.push(() => {
      env.fetch = original;
    });
  }
  const xhrProto = env.XMLHttpRequest?.prototype;
  if (xhrProto && typeof xhrProto.open === 'function' && typeof xhrProto.send === 'function') {
    const origOpen = xhrProto.open;
    const origSend = xhrProto.send;
    xhrProto.open = function (method, url, ...rest) {
      this.__byoUrl = url;
      return origOpen.call(this, method, url, ...rest);
    };
    xhrProto.send = function (...args) {
      note('xhr', this.__byoUrl || '');
      return origSend.apply(this, args);
    };
    restore.push(() => {
      xhrProto.open = origOpen;
      xhrProto.send = origSend;
    });
  }
  const nav = env.navigator;
  if (nav && typeof nav.sendBeacon === 'function') {
    const original = nav.sendBeacon;
    nav.sendBeacon = function (url, ...rest) {
      note('beacon', url);
      return original.call(this, url, ...rest);
    };
    restore.push(() => {
      nav.sendBeacon = original;
    });
  }

  try {
    const result = await fn();
    return { result, count: calls.length, calls };
  } finally {
    for (const undo of restore.reverse()) undo();
  }
}

// ---- src/elements/byo-data.js
const PRIVACY_LINE = 'Processed in your browser. Nothing is uploaded.';
const DEFAULT_LABEL = 'Drop a CSV, JSON or NDJSON file here';
const DEFAULT_PLACEHOLDER = 'name,score\nAda,12';
const DEFAULT_ACCEPT = '.csv,.json,.ndjson,.jsonl,.txt,text/csv,application/json';

// <byo-data sample-url="sample.csv" max-bytes="5242880"></byo-data>
//
//   Attributes (all optional)
//     sample-url         adds a "Use sample data" button
//     max-bytes          size limit, default 5 MiB
//     label              heading of the drop zone
//     paste-placeholder  placeholder text of the paste box
//     accept             accept value of the file picker, also shown as a hint
//     hide-paste         hides the paste box
//
//   el.validate = (data) => string[]     optional; any strings are shown as errors
//   el.addEventListener('byo-data', (e) => e.detail)   { data, name, source, bytes }
//   el.value, el.load(text, { name, source }), el.clear()
class ByoData extends ElementBase {
  constructor() {
    super();
    this._value = null;
    this._root = this.attachShadow({ mode: 'open' });
    applyStyles(this._root, BASE_CSS + DATA_CSS);
    this._build();
  }

  get value() {
    return this._value;
  }

  get maxBytes() {
    const n = Number(this.getAttribute('max-bytes'));
    return Number.isFinite(n) && n > 0 ? n : DEFAULT_MAX_BYTES;
  }

  _build() {
    const sampleUrl = this.getAttribute('sample-url');
    this._file = h('input', {
      type: 'file',
      hidden: true,
      'aria-label': 'Choose a data file',
      accept: DEFAULT_ACCEPT,
    });
    this._pick = h('button', { type: 'button', part: 'button primary', class: 'primary' }, 'Choose file');
    this._sample = h('button', { type: 'button', part: 'button', hidden: !sampleUrl }, 'Use sample data');
    this._title = h('strong', null, DEFAULT_LABEL);
    this._hint = h('span', { class: 'hint', part: 'hint', hidden: true });
    this._dz = h(
      'div',
      { class: 'dz', part: 'dropzone', role: 'group', 'aria-label': 'Drop a data file here' },
      this._title,
      this._hint,
      h('div', { class: 'row' }, this._pick, this._sample, this._file),
    );
    this._text = h('textarea', {
      id: 'paste',
      part: 'textarea',
      rows: '2',
      spellcheck: 'false',
      placeholder: DEFAULT_PLACEHOLDER,
    });
    this._use = h('button', { type: 'button', part: 'button' }, 'Use pasted data');
    this._paste = h(
      'div',
      { class: 'paste' },
      h('label', { for: 'paste', part: 'label' }, 'Or paste data'),
      h('div', { class: 'pr' }, this._text, this._use),
    );
    this._privacy = h('p', { class: 'privacy', part: 'privacy' }, PRIVACY_LINE);
    this._status = h('p', { class: 'status', part: 'status', role: 'status', 'aria-live': 'polite' });
    this._errors = h('ul', { class: 'errors', part: 'errors', role: 'alert', hidden: true });
    this._root.append(h('section', { class: 'box', part: 'box' }, this._dz, this._paste, this._privacy, this._status, this._errors));

    this._applyOptions();
    this._pick.addEventListener('click', () => this._file.click());
    this._file.addEventListener('change', () => {
      const f = this._file.files && this._file.files[0];
      this._file.value = '';
      if (f) this._readFile(f);
    });
    this._sample.addEventListener('click', () => this._loadSample());
    this._use.addEventListener('click', () => {
      const text = this._text.value;
      this.load(text, { name: 'pasted data', source: 'paste' });
    });
    for (const type of ['dragenter', 'dragover']) {
      this._dz.addEventListener(type, (e) => {
        e.preventDefault();
        this.setAttribute('dragging', '');
      });
    }
    this._dz.addEventListener('dragleave', () => this.removeAttribute('dragging'));
    this._dz.addEventListener('drop', (e) => {
      e.preventDefault();
      this.removeAttribute('dragging');
      const files = e.dataTransfer?.files;
      if (files && files.length) this._readFile(files[0], files.length > 1);
    });
  }

  static get observedAttributes() {
    return ['sample-url', 'label', 'paste-placeholder', 'accept', 'hide-paste'];
  }

  attributeChangedCallback() {
    if (this._sample) this._applyOptions();
  }

  // Reads the display attributes. An empty or missing value restores the default.
  _applyOptions() {
    this._sample.hidden = !this.getAttribute('sample-url');
    this._title.textContent = this.getAttribute('label') || DEFAULT_LABEL;
    this._text.setAttribute('placeholder', this.getAttribute('paste-placeholder') || DEFAULT_PLACEHOLDER);
    const accept = (this.getAttribute('accept') || '').trim();
    this._file.setAttribute('accept', accept || DEFAULT_ACCEPT);
    this._hint.textContent = accept ? 'Accepted: ' + accept.split(',').map((t) => t.trim()).filter(Boolean).join(', ') : '';
    this._hint.hidden = !accept;
    this._paste.hidden = this.hasAttribute('hide-paste');
  }

  clear() {
    this._value = null;
    this._status.textContent = '';
    this._status.removeAttribute('data-tone');
    this._showErrors([]);
  }

  async _readFile(file, extra = false) {
    const tooBig = checkSize(file.size, this.maxBytes);
    if (tooBig) return this._fail([file.name + ': ' + tooBig]);
    let text;
    try {
      text = await file.text();
    } catch {
      return this._fail(['Could not read ' + file.name + '.']);
    }
    await this.load(text, { name: file.name, source: 'file', bytes: file.size, note: extra ? 'Using the first file only.' : '' });
  }

  async _loadSample() {
    const url = this.getAttribute('sample-url');
    if (!url) return;
    let text;
    try {
      const res = await fetch(url);
      if (!res.ok) throw new Error('HTTP ' + res.status);
      text = await res.text();
    } catch {
      return this._fail(['Could not load the sample data.']);
    }
    const name = decodeURIComponent(new URL(url, location.href).pathname.split('/').pop() || 'sample');
    await this.load(text, { name, source: 'sample' });
  }

  // Parse, validate and announce. Everything inside the guard is the
  // "processing" the page can truthfully report on.
  async load(text, { name = 'data', source = 'paste', bytes, note = '' } = {}) {
    const size = bytes ?? byteLength(text);
    const tooBig = checkSize(size, this.maxBytes);
    if (tooBig) return this._fail([tooBig]);
    let outcome;
    try {
      outcome = await countNetworkCalls(() => {
        const { data } = parseText(text, { name });
        let problems = [];
        if (typeof this.validate === 'function') {
          const r = this.validate(data);
          problems = Array.isArray(r) ? r.map(String) : [];
        }
        if (problems.length === 0) {
          const detail = { data, name, source, bytes: size };
          this._value = detail;
          this.dispatchEvent(new CustomEvent('byo-data', { detail, bubbles: true, composed: true }));
        }
        return { data, problems };
      });
    } catch (e) {
      return this._fail([e.message || 'Could not read that data.']);
    }
    const { problems } = outcome.result;
    if (problems.length) return this._fail(problems);
    this._showErrors([]);
    const { data } = outcome.result;
    const n = Array.isArray(data) ? data.length + (data.length === 1 ? ' record' : ' records') : 'one value';
    const net =
      outcome.count === 0
        ? '0 network requests while processing.'
        : outcome.count + ' network request' + (outcome.count === 1 ? '' : 's') + ' while processing (' + outcome.calls[0].url + ').';
    this._setStatus(
      'Loaded ' + name + ': ' + n + ', ' + formatBytes(size) + '. ' + net + (note ? ' ' + note : ''),
      outcome.count === 0 ? 'good' : 'warn',
    );
    return this._value;
  }

  _setStatus(text, tone) {
    this._status.textContent = text;
    if (tone) this._status.setAttribute('data-tone', tone);
    else this._status.removeAttribute('data-tone');
  }

  _showErrors(list) {
    this._errors.replaceChildren(...list.map((m) => h('li', null, m)));
    this._errors.hidden = list.length === 0;
  }

  _fail(list) {
    this._value = null;
    this._setStatus('Nothing was loaded.', 'bad');
    this._showErrors(list);
    this.dispatchEvent(new CustomEvent('byo-data-error', { detail: { errors: list }, bubbles: true, composed: true }));
  }
}

defineOnce('byo-data', ByoData);

// ---- src/core/providers.js
// Provider descriptors for <byo-key>. Plain data, so they can be JSON.
//
//   id          short name, used in events and storage names
//   label       shown to people
//   keyPattern  regex (RegExp or string) a key must match
//   docsUrl     where to get a key
//   mode        'direct'  the browser calls the provider
//               'relay'   the browser calls a stateless relay on your origin
//   endpoint    provider base URL (direct) or upstream base URL (relay)
//   relayPath   path of the relay on your origin (relay mode)
//   auth        { header, prefix } for the key
//   headers     extra fixed request headers
//   testPath    optional cheap GET path used by createKeyTest()
//   note        optional sentence shown under the route statement

const openai = Object.freeze({
  id: 'openai',
  label: 'OpenAI',
  keyPattern: '^sk-[A-Za-z0-9_-]{20,}$',
  docsUrl: 'https://platform.openai.com/api-keys',
  mode: 'direct',
  endpoint: 'https://api.openai.com',
  auth: Object.freeze({ header: 'authorization', prefix: 'Bearer ' }),
  headers: Object.freeze({}),
  testPath: '/v1/models',
});

// Anthropic only allows browser calls when this header is sent. The header name
// says it plainly: the key is exposed to the page, so use a key you can revoke.
const anthropic = Object.freeze({
  id: 'anthropic',
  label: 'Anthropic',
  keyPattern: '^sk-ant-[A-Za-z0-9_-]{20,}$',
  docsUrl: 'https://console.anthropic.com/settings/keys',
  mode: 'direct',
  endpoint: 'https://api.anthropic.com',
  note:
    'Browser calls send the header anthropic-dangerous-direct-browser-access: true. Use a key you can revoke.',
  auth: Object.freeze({ header: 'x-api-key', prefix: '' }),
  headers: Object.freeze({
    'anthropic-version': '2023-06-01',
    'anthropic-dangerous-direct-browser-access': 'true',
  }),
  testPath: '/v1/models',
});

// OpenRouter answers browser preflights for /api/v1/chat/completions and
// /api/alpha/decisions with access-control-allow-origin: * and allows the
// Authorization, Content-Type, HTTP-Referer and X-Title headers, so the browser
// calls it directly. One key reaches many models. GET /api/v1/key is a cheap
// key test: it returns the key's label and limit.
const openrouter = Object.freeze({
  id: 'openrouter',
  label: 'OpenRouter',
  keyPattern: '^sk-or-v1-[A-Fa-f0-9]{64}$',
  docsUrl: 'https://openrouter.ai/settings/keys',
  mode: 'direct',
  endpoint: 'https://openrouter.ai',
  note: 'Make a key with a small credit limit for this demo, so a leaked key can only spend a little.',
  auth: Object.freeze({ header: 'authorization', prefix: 'Bearer ' }),
  headers: Object.freeze({}),
  testPath: '/api/v1/key',
});

const PROVIDERS = Object.freeze({ openrouter, openai, anthropic });

function getProvider(id) {
  return PROVIDERS[id] || null;
}

const NORMALIZED = new WeakSet();
const ensure = (p) => (NORMALIZED.has(p) ? p : normalizeProvider(p));

function normalizeProvider(d) {
  if (!d || typeof d !== 'object') throw new TypeError('A provider descriptor must be an object.');
  for (const k of ['id', 'label', 'mode', 'endpoint']) {
    if (typeof d[k] !== 'string' || !d[k]) throw new TypeError('Provider descriptor needs a string "' + k + '".');
  }
  if (d.mode !== 'direct' && d.mode !== 'relay') throw new TypeError('Provider mode must be "direct" or "relay".');
  if (d.mode === 'relay' && !(typeof d.relayPath === 'string' && d.relayPath.startsWith('/'))) {
    throw new TypeError('A relay provider needs a relayPath that starts with "/".');
  }
  let pattern = null;
  if (d.keyPattern) {
    pattern = d.keyPattern instanceof RegExp ? d.keyPattern : new RegExp(d.keyPattern);
  }
  const out = {
    id: d.id,
    label: d.label,
    keyPattern: pattern,
    docsUrl: d.docsUrl || '',
    note: d.note || '',
    mode: d.mode,
    endpoint: d.endpoint.replace(/\/+$/, ''),
    relayPath: d.mode === 'relay' ? d.relayPath.replace(/\/+$/, '') : '',
    auth: { header: (d.auth?.header || 'authorization').toLowerCase(), prefix: d.auth?.prefix ?? 'Bearer ' },
    headers: { ...(d.headers || {}) },
    testPath: d.testPath || '',
  };
  NORMALIZED.add(out);
  return out;
}

// Returns an error message, or null when the key looks right.
function checkKeyFormat(provider, key) {
  const p = ensure(provider);
  if (typeof key !== 'string' || !key.trim()) return 'Enter a key.';
  if (p.keyPattern && !p.keyPattern.test(key.trim())) {
    return 'That does not match the ' + p.label + ' key format. Check you copied all of it.';
  }
  return null;
}

function hostOf(url) {
  try {
    return new URL(url).host;
  } catch {
    return url;
  }
}

// Plain statement of where the key goes.
function describeRoute(provider, origin = '') {
  const p = ensure(provider);
  const host = hostOf(p.endpoint);
  if (p.mode === 'direct') {
    return {
      kind: 'direct',
      url: p.endpoint,
      text: 'Your key goes straight from your browser to ' + host + '. This site never receives it.',
    };
  }
  const relay = origin + p.relayPath;
  return {
    kind: 'relay',
    url: relay,
    text:
      'Browsers cannot call ' + host + ' directly. Your key goes through a stateless relay at ' + relay +
      ' that forwards the request to ' + host + ' and stores nothing. The relay sees the key while it passes through.',
  };
}

// Where a request for `path` (for example "/v1/messages") should be sent.
function requestFor(provider, key, path, origin = '') {
  const p = ensure(provider);
  const base = p.mode === 'relay' ? origin + p.relayPath : p.endpoint;
  return {
    url: base + path,
    headers: { ...p.headers, [p.auth.header]: p.auth.prefix + key.trim() },
  };
}

// Builds a test hook for <byo-key>: one cheap GET to the provider.
function createKeyTest(provider, { fetchImpl, origin = '' } = {}) {
  const p = normalizeProvider(provider);
  return async (key) => {
    if (!p.testPath) return { ok: true, message: 'Format looks right. This provider has no test call.' };
    const doFetch = fetchImpl || globalThis.fetch;
    const { url, headers } = requestFor(p, key, p.testPath, origin);
    let res;
    try {
      res = await doFetch(url, { method: 'GET', headers });
    } catch {
      return { ok: false, message: 'Could not reach ' + hostOf(url) + '. Check your connection or the relay.' };
    }
    if (res.ok) return { ok: true, message: p.label + ' accepted the key.' };
    if (res.status === 401 || res.status === 403) return { ok: false, message: p.label + ' rejected the key (HTTP ' + res.status + ').' };
    return { ok: false, message: p.label + ' answered HTTP ' + res.status + '.' };
  };
}

// ---- src/core/key-store.js
// Holds one key per provider. Memory is the default. sessionStorage is the only
// persistent option, and only when the user chooses it. Nothing else ever keeps a key.

const PREFIX = 'byo-kit:key:';

function createKeyStore({ mode = 'memory', session } = {}) {
  const memory = new Map();
  let current = mode === 'session' ? 'session' : 'memory';
  const sess = () => {
    try {
      return session || globalThis.sessionStorage || null;
    } catch {
      return null;
    }
  };
  return {
    get mode() {
      return current;
    },
    get(id) {
      if (current === 'session') {
        const s = sess();
        return (s && s.getItem(PREFIX + id)) || null;
      }
      return memory.get(id) || null;
    },
    set(id, key) {
      if (current === 'session') {
        const s = sess();
        if (!s) throw new Error('sessionStorage is not available here.');
        s.setItem(PREFIX + id, key);
      } else {
        memory.set(id, key);
      }
    },
    clear(id) {
      memory.delete(id);
      const s = sess();
      if (s) s.removeItem(PREFIX + id);
    },
    // Move any held key to the new place and wipe the old one.
    setMode(next, id) {
      const target = next === 'session' ? 'session' : 'memory';
      if (target === current) return;
      const key = this.get(id);
      this.clear(id);
      current = target;
      if (key) this.set(id, key);
    },
  };
}

function maskKey(key) {
  if (!key) return '';
  const k = key.trim();
  return k.length <= 8 ? '••••' : k.slice(0, 3) + '…' + k.slice(-4);
}

// ---- src/elements/byo-key.js
// <byo-key provider="anthropic" storage="memory"></byo-key>
//
//   el.provider = 'openai' | descriptor object
//   el.test = async (key, provider) => ({ ok, message })   optional
//   el.getKey() -> string | null
//   el.addEventListener('byo-key', (e) => e.detail)
//     { provider, state: 'set'|'forgotten'|'tested', hasKey, storage, ok?, message? }
//
// The event never carries the key. Call getKey() when you need it.
class ByoKey extends ElementBase {
  constructor() {
    super();
    this._provider = null;
    this._test = null;
    this._store = createKeyStore({ mode: 'memory' });
    this._root = this.attachShadow({ mode: 'open' });
    applyStyles(this._root, BASE_CSS + KEY_CSS);
  }

  static get observedAttributes() {
    return ['provider', 'relay-origin'];
  }

  connectedCallback() {
    // Attributes are not readable in the constructor for parser-created elements.
    if (!this._storageRead) {
      this._storageRead = true;
      if (this.getAttribute('storage') === 'session') {
        try {
          this._store.setMode('session', '');
        } catch {
          /* stays in memory */
        }
      }
    }
    // Properties set before this element was defined sit on the instance.
    for (const prop of ['provider', 'test']) {
      if (Object.prototype.hasOwnProperty.call(this, prop)) {
        const value = this[prop];
        delete this[prop];
        this[prop] = value;
      }
    }
    if (!this._provider && this.getAttribute('provider')) this.provider = this.getAttribute('provider');
    if (!this._built) this._render();
  }

  attributeChangedCallback(name) {
    if (name === 'provider' && this.isConnected) this.provider = this.getAttribute('provider');
    if (name === 'relay-origin' && this._built) this._render();
  }

  get provider() {
    return this._provider;
  }

  set provider(value) {
    try {
      const d = typeof value === 'string' ? getProvider(value) : value;
      if (!d) throw new TypeError('Unknown provider "' + value + '".');
      this._provider = normalizeProvider(d);
      this._providerError = '';
    } catch (e) {
      this._provider = null;
      this._providerError = e.message;
    }
    if (this.isConnected) this._render();
  }

  get test() {
    return this._test;
  }

  set test(fn) {
    this._test = typeof fn === 'function' ? fn : null;
    if (this._built && this._testBtn) this._testBtn.hidden = !this._test;
  }

  get storage() {
    return this._store.mode;
  }

  getKey() {
    return this._provider ? this._store.get(this._provider.id) : null;
  }

  _origin() {
    return this.getAttribute('relay-origin') || globalThis.location?.origin || '';
  }

  _emit(state, extra = {}) {
    const detail = {
      provider: this._provider ? this._provider.id : null,
      state,
      hasKey: !!this.getKey(),
      storage: this._store.mode,
      ...extra,
    };
    this.dispatchEvent(new CustomEvent('byo-key', { detail, bubbles: true, composed: true }));
  }

  _render() {
    this._built = true;
    this._root.replaceChildren();
    const p = this._provider;
    if (!p) {
      this._root.append(
        h('section', { class: 'box', part: 'box' }, h('p', { class: 'status', 'data-tone': 'bad', role: 'alert' }, this._providerError || 'Set a provider for this element.')),
      );
      return;
    }
    const route = describeRoute(p, this._origin());
    const held = this._store.get(p.id);

    this._input = h('input', {
      id: 'key',
      type: 'password',
      part: 'input',
      autocomplete: 'off',
      autocapitalize: 'off',
      spellcheck: 'false',
      'data-1p-ignore': true,
      'data-lpignore': 'true',
      placeholder: 'Paste your ' + p.label + ' key',
    });
    if (held) this._input.value = held;
    this._show = h('button', { type: 'button', part: 'button', 'aria-pressed': 'false', 'aria-label': 'Show key' }, 'Show');
    this._use = h('button', { type: 'button', part: 'button primary', class: 'primary' }, 'Use key');
    this._forget = h('button', { type: 'button', part: 'button', class: 'link' }, 'Forget key');
    this._testBtn = h('button', { type: 'button', part: 'button', hidden: !this._test }, 'Test key');
    this._status = h('p', { class: 'status', part: 'status', role: 'status', 'aria-live': 'polite' });
    this._error = h('ul', { class: 'errors', part: 'errors', role: 'alert', hidden: true });

    const radio = (value, text) =>
      h(
        'label',
        { class: 'choice', part: 'choice' },
        h('input', { type: 'radio', name: 'storage', value, checked: this._store.mode === value }),
        text,
      );
    const fieldset = h(
      'div',
      { class: 'keep', role: 'radiogroup', 'aria-label': 'Where to keep the key' },
      h('span', { class: 'lead', 'aria-hidden': 'true' }, 'Keep it'),
      radio('memory', 'In memory (default)'),
      radio('session', 'In sessionStorage'),
    );

    const routeBox = h('p', { class: 'route', part: 'route' }, route.text);
    if (p.note) routeBox.append(h('span', { class: 'note' }, p.note));
    // Memory is gone on reload. sessionStorage is gone when the tab closes.
    fieldset.title = 'Memory: gone when you reload. sessionStorage: gone when you close the tab.';

    const head = h('div', { class: 'head' }, h('label', { for: 'key', part: 'label' }, p.label + ' API key'));
    if (p.docsUrl) {
      head.append(h('a', { href: p.docsUrl, target: '_blank', rel: 'noopener noreferrer', part: 'link' }, 'Get a key'));
    }

    this._root.append(
      h(
        'section',
        { class: 'box', part: 'box' },
        head,
        h('div', { class: 'field' }, h('div', { class: 'row' }, h('div', { class: 'grow' }, this._input), this._show, this._use)),
        h('div', { class: 'row actions' }, this._testBtn, this._forget),
        fieldset,
        routeBox,
        this._status,
        this._error,
      ),
    );
    this._wire(fieldset);
    this._refresh();
  }

  _wire(fieldset) {
    this._show.addEventListener('click', () => {
      const show = this._input.type === 'password';
      this._input.type = show ? 'text' : 'password';
      this._show.textContent = show ? 'Hide' : 'Show';
      this._show.setAttribute('aria-pressed', String(show));
      this._show.setAttribute('aria-label', show ? 'Hide key' : 'Show key');
    });
    this._use.addEventListener('click', () => this._save());
    this._input.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') {
        e.preventDefault();
        this._save();
      }
    });
    this._forget.addEventListener('click', () => this._forgetKey());
    this._testBtn.addEventListener('click', () => this._runTest());
    fieldset.addEventListener('change', (e) => {
      if (e.target.name !== 'storage') return;
      try {
        this._store.setMode(e.target.value, this._provider.id);
      } catch (err) {
        this._store.setMode('memory', this._provider.id);
        this._showError([err.message]);
      }
      for (const r of fieldset.querySelectorAll('input')) r.checked = r.value === this._store.mode;
      this._refresh();
      this._emit('set');
    });
  }

  _showError(list) {
    this._error.replaceChildren(...list.map((m) => h('li', null, m)));
    this._error.hidden = list.length === 0;
  }

  _setStatus(text, tone) {
    this._status.textContent = text;
    if (tone) this._status.setAttribute('data-tone', tone);
    else this._status.removeAttribute('data-tone');
  }

  _refresh() {
    const key = this.getKey();
    this._forget.disabled = !key;
    this._testBtn.disabled = !key;
    if (key) {
      const where = this._store.mode === 'session' ? 'in sessionStorage for this tab' : 'in memory';
      this._setStatus('Key ready (' + maskKey(key) + '), held ' + where + '.', 'good');
    } else {
      this._setStatus('No key set. Features that need a key stay off.');
    }
  }

  _save() {
    const value = this._input.value.trim();
    const problem = checkKeyFormat(this._provider, value);
    if (problem) {
      this._showError([problem]);
      return;
    }
    this._showError([]);
    try {
      this._store.set(this._provider.id, value);
    } catch (err) {
      this._showError([err.message]);
      return;
    }
    this._refresh();
    this._emit('set');
  }

  _forgetKey() {
    this._store.clear(this._provider.id);
    this._input.value = '';
    this._showError([]);
    this._refresh();
    this._emit('forgotten');
  }

  async _runTest() {
    const key = this.getKey();
    if (!key || !this._test) return;
    this.setAttribute('data-test', 'running');
    this._testBtn.disabled = true;
    this._setStatus('Testing the key…');
    let result;
    try {
      result = await this._test(key, this._provider);
    } catch {
      result = { ok: false, message: 'The test call failed.' };
    }
    const ok = !!(result && result.ok);
    const message = (result && result.message) || (ok ? 'The key works.' : 'The key did not work.');
    this.setAttribute('data-test', ok ? 'ok' : 'fail');
    this._testBtn.disabled = !this.getKey();
    this._setStatus(message, ok ? 'good' : 'bad');
    this._emit('tested', { ok, message });
  }
}

defineOnce('byo-key', ByoKey);

// ---- src/core/csv-export.js
// CSV output that is safe to open in a spreadsheet.
// A cell that starts with = + - @ tab or CR can run as a formula in Excel,
// Sheets and LibreOffice. We prefix such text with an apostrophe.

const NUMERIC = /^[+-]?(\d+\.?\d*|\.\d+)([eE][+-]?\d+)?$/;

function neutralizeFormula(value) {
  const s = String(value);
  if (s === '') return s;
  if (NUMERIC.test(s)) return s; // plain numbers stay numbers
  return /^[=+\-@\t\r]/.test(s) ? "'" + s : s;
}

function csvCell(value) {
  if (value === null || value === undefined) return '';
  let s = typeof value === 'object' ? JSON.stringify(value) : String(value);
  s = neutralizeFormula(s);
  return /[",\r\n]|^\s|\s$/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
}

// rows: array of arrays, or array of objects (columns default to the union of keys).
function toCsv(rows, columns) {
  const objects = rows.length > 0 && !Array.isArray(rows[0]);
  let head = columns;
  let body = rows;
  if (objects) {
    head = head || [...new Set(rows.flatMap((r) => Object.keys(r)))];
    body = rows.map((r) => head.map((k) => r[k]));
  }
  const lines = [];
  if (head) lines.push(head.map(csvCell).join(','));
  for (const r of body) lines.push(r.map(csvCell).join(','));
  return lines.join('\r\n') + '\r\n';
}

// ---- src/core/openrouter.js
// OpenRouter Decisions API helper. No DOM, so it runs under node --test.
//
//   const { answers } = await openrouterDecide({
//     key, state: { ticket: '...' },
//     questions: {
//       topic:  { type: 'choice', instructions: 'Which team handles `ticket`?',
//                 criteria: { billing: 'Charges and invoices', bug: 'Something broken', other: null } },
//       urgent: { type: 'noul',   instructions: '`ticket` asks for help today' },
//       anger:  { type: 'score',  instructions: 'How upset is the writer?', criteria: ['Calm', 'Annoyed', 'Furious'] },
//     },
//   });
//   answers.topic   // { type: 'choice', choice, probabilities, confidence }
//   answers.urgent  // { type: 'noul', noul }    probability of yes, 0..1
//   answers.anger   // { type: 'score', score, probabilities, confidence }
//
// The default model is TypeSafe's Jev. Every answer is checked against its question:
// a choice must be one of the criteria keys, a noul a number in [0, 1], a score a
// number within the levels. Anything else throws.

const DECISIONS_URL = 'https://openrouter.ai/api/alpha/decisions';
const JEV_MODEL = 'typesafe/jev-1.14';

class OpenRouterError extends Error {
  constructor(message, status = 0) {
    super(message);
    this.name = 'OpenRouterError';
    this.status = status;
  }
}

const scrub = (text, key) => (key ? String(text).split(key).join('[key]') : String(text));

const TYPES = new Set(['choice', 'score', 'noul']);

function checkQuestion(id, q) {
  if (!q || typeof q !== 'object' || !TYPES.has(q.type)) throw new TypeError('Question "' + id + '" needs type choice, score or noul.');
  if (!q.instructions) throw new TypeError('Question "' + id + '" needs instructions.');
  if (q.type === 'choice' && (!q.criteria || typeof q.criteria !== 'object' || Array.isArray(q.criteria) || Object.keys(q.criteria).length < 2)) {
    throw new TypeError('Choice question "' + id + '" needs criteria: an object with at least two options.');
  }
  if (q.type === 'score' && (!Array.isArray(q.criteria) || q.criteria.length < 2)) {
    throw new TypeError('Score question "' + id + '" needs criteria: a list of at least two levels, lowest first.');
  }
}

const inRange = (n, lo, hi) => typeof n === 'number' && Number.isFinite(n) && n >= lo && n <= hi;

function checkAnswer(id, q, a, status) {
  const fail = (why) => { throw new OpenRouterError('Question "' + id + '": ' + why, status); };
  if (!a || typeof a !== 'object') fail('no answer came back.');
  if (q.type === 'choice') {
    const options = Object.keys(q.criteria);
    if (!options.includes(a.choice)) fail('the model chose "' + a.choice + '", which is not one of: ' + options.join(', ') + '.');
  } else if (q.type === 'noul') {
    if (!inRange(a.noul, 0, 1)) fail('expected a probability between 0 and 1.');
  } else if (!inRange(a.score, 0, q.criteria.length - 1)) {
    fail('expected a score between 0 and ' + (q.criteria.length - 1) + '.');
  }
}

function statusHint(status, model) {
  if (status === 401) {
    return 'OpenRouter rejected the key (HTTP 401). Check you copied all of it, or make a new one at https://openrouter.ai/settings/keys.';
  }
  if (status === 402) {
    return 'OpenRouter says the key is out of credit or over its limit (HTTP 402). Add credit or raise the key limit.';
  }
  if (status === 404) {
    return model.startsWith('typesafe/')
      ? 'OpenRouter answered HTTP 404 for ' + model + '. Jev may be blocked by your OpenRouter guardrails. Check the guardrail settings for your account.'
      : 'OpenRouter answered HTTP 404 for ' + model + '. The model name may be wrong, or your OpenRouter guardrails may block it.';
  }
  return '';
}

async function openrouterDecide({ key, model = JEV_MODEL, state, questions, fetch: fetchImpl } = {}) {
  if (typeof key !== 'string' || !key.trim()) throw new TypeError('Enter an OpenRouter key.');
  if (!questions || typeof questions !== 'object' || Array.isArray(questions) || !Object.keys(questions).length) {
    throw new TypeError('Give at least one question, as an object of id to question.');
  }
  for (const [id, q] of Object.entries(questions)) checkQuestion(id, q);
  const doFetch = fetchImpl || globalThis.fetch;
  const apiKey = key.trim();
  let res;
  try {
    res = await doFetch(DECISIONS_URL, {
      method: 'POST',
      headers: { authorization: 'Bearer ' + apiKey, 'content-type': 'application/json' },
      body: JSON.stringify({ model, state, questions }),
    });
  } catch {
    throw new OpenRouterError('Could not reach openrouter.ai. Check your connection.');
  }
  let json = null;
  try {
    json = await res.json();
  } catch {
    /* not JSON */
  }
  if (!res.ok) {
    const hint = statusHint(res.status, model);
    const detail = json?.error?.message ? ' ' + scrub(json.error.message, apiKey) : '';
    throw new OpenRouterError(hint ? hint + detail : 'OpenRouter answered HTTP ' + res.status + '.' + detail, res.status);
  }
  const answers = json?.answers;
  if (!answers || typeof answers !== 'object') throw new OpenRouterError('OpenRouter returned no answers.', res.status);
  for (const [id, q] of Object.entries(questions)) checkAnswer(id, q, answers[id], res.status);
  return { model: json.model || model, answers };
}

